require dirname(__DIR__).'/includes/bootstrap.php';require_staff_or_admin();$rows=fetch_all("SELECT s.*,m.m_fname,m.m_name,m.m_lname,m.m_email,d.d_name,d.d_id,d.d_img,t.t_name FROM tbl_devices_service s JOIN tbl_member m ON m.m_id=s.ref_m_id JOIN tbl_devices d ON d.d_id=s.ref_d_id LEFT JOIN tbl_devices_type t ON t.t_id=s.ref_t_id WHERE s.ser_status='returned' ORDER BY s.ser_date_return DESC,s.ser_id DESC");render_header('ประวัติการคืน','returns');?>
<div class="page-intro"><div><h2>ประวัติการคืนครุภัณฑ์</h2><p>ตรวจสอบวันที่ยืม วันที่คืน ผู้ยืม และเจ้าหน้าที่ที่รับคืน</p></div><button class="btn btn-soft" onclick="window.print()">พิมพ์</button></div><div class="card"><div class="table-tools"><div class="table-search"><input type="search" placeholder="ค้นหาประวัติ…" data-table-search="#returnTable"></div><span class="table-meta"><?=count($rows)?> รายการ</span></div><div class="table-wrap"><table class="data-table" id="returnTable"><thead><tr><th>ครุภัณฑ์</th><th>ผู้ยืม</th><th>วันที่ยืม</th><th>วันที่คืน</th><th>ผู้รับคืน</th><th>วัตถุประสงค์</th></tr></thead><tbody><?php if(!$rows):?><tr data-empty><td colspan="6"><div class="empty-state"><div class="empty-icon">↙</div><h3>ยังไม่มีประวัติการคืน</h3></div></td></tr><?php else:foreach($rows as $r):?><tr><td><b class="cell-title"><?=e($r['d_name'])?></b><small class="cell-sub"><?=e($r['d_id'])?> • <?=e($r['t_name']?:'-')?></small></td><td><?=e(full_name($r))?></td><td><?=e(thai_date($r['ser_date_lend']))?></td><td><span class="badge badge-success"><?=e(thai_date($r['ser_date_return']))?></span></td><td><?=e($r['ser_staff_name_return']?:'-')?></td><td><?=e($r['ser_reason'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php render_footer();?>
